import numpy as np

def fit_kappa(times, rates, theta):
    """Recover kappa from points on theta + (r0 - theta) e^(-kappa t)."""
    t = np.asarray(times, dtype=float)
    gap = np.asarray(rates, dtype=float) - theta
    if np.any(gap == 0):
        raise ValueError("a rate equals theta, so its log gap is undefined")
    slope, _ = np.polyfit(t, np.log(np.abs(gap)), 1)
    return float(-slope)
